values
 ('hc-demo-tomato',1,'TEST ONLY: Tomato encyclopedia card','A food-learning example. Tomato varieties and preparation differ. This demo entry makes no gout, sleep or treatment claim.','tomato','not_assessed','TEST ONLY. No clinical effect has been assessed.','[{"title":"USDA FoodData Central — tomato food search","url":"https://fdc.nal.usda.gov/food-search/?query=tomato"}]'::jsonb,'TEST ONLY. This fixture is not a personalized food recommendation.','[]'::jsonb,'{"demo_only":true,"category":"vegetable / culinary fruit","topic_tags":["sleep-better","gout-uric-acid"],"fixture_label":"TEST ONLY - NOT HUMAN REVIEWED"}'::jsonb,'test-fixture',now()),
 ('hc-demo-potato',1,'TEST ONLY: Potato','Food-learning example. Composition varies by variety and preparation; no condition or treatment claim is made.','potato','not_assessed','TEST ONLY. No clinical effect assessed.','[{"title":"USDA FoodData Central — potato food search","url":"https://fdc.nal.usda.gov/food-search/?query=potato"}]'::jsonb,'TEST ONLY. General education only, not personal advice.','[]'::jsonb,'{"demo_only":true,"category":"vegetable / tuber","topic_tags":["sleep-better","gout-uric-acid"],"fixture_label":"TEST ONLY - NOT HUMAN REVIEWED"}'::jsonb,'test-fixture',now()),
 ('hc-demo-cherries',1,'TEST ONLY: Cherries','Fruit-learning example. Fresh, frozen, dried and juice forms differ. No symptom, gout or sleep outcome claim is made.','cherries','not_assessed','TEST ONLY. No clinical effect assessed.','[{"title":"USDA FoodData Central — cherries food search","url":"https://fdc.nal.usda.gov/food-search/?query=cherries"}]'::jsonb,'TEST ONLY. Do not use this example to change care or treatment.','[]'::jsonb,'{"demo_only":true,"category":"fruit","topic_tags":["sleep-better","gout-uric-acid"],"fixture_label":"TEST ONLY - NOT HUMAN REVIEWED"}'::jsonb,'test-fixture',now()),
 ('hc-demo-ginger',1,'TEST ONLY: Ginger','Culinary botanical example: ginger is commonly used as a spice. This is a food-context note only, with no efficacy claim.','ginger','not_assessed','TEST ONLY. No clinical effect assessed.','[{"title":"USDA FoodData Central — ginger food search","url":"https://fdc.nal.usda.gov/food-search/?query=ginger"}]'::jsonb,'TEST ONLY. Botanicals can interact with medicines and may not suit everyone.','[]'::jsonb,'{"demo_only":true,"category":"herb and spice","topic_tags":["sleep-better","gout-uric-acid"],"fixture_label":"TEST ONLY - NOT HUMAN REVIEWED"}'::jsonb,'test-fixture',now()),
 ('hc-demo-water',1,'TEST ONLY: Water and hydration','Plain water is calorie-free. Water needs vary by person and context; this card gives no personal intake target.','water','not_assessed','TEST ONLY fixture, not a reviewed recommendation.','[{"title":"CDC — About Water and Healthier Drinks","url":"https://www.cdc.gov/healthy-weight-growth/water-healthy-drinks/"}]'::jsonb,'TEST ONLY. Follow clinician guidance if you have a fluid restriction or condition affecting fluid intake.','[]'::jsonb,'{"demo_only":true,"category":"drink","topic_tags":["sleep-better","gout-uric-acid"],"fixture_label":"TEST ONLY - NOT HUMAN REVIEWED"}'::jsonb,'test-fixture',now()),
 ('hc-demo-walking',1,'TEST ONLY: Gentle walking','Movement-learning example with no prescribed speed, duration or frequency. This fixture does not assess individual safety.','footprints','not_assessed','TEST ONLY. No effect or suitability assessed.','[]'::jsonb,'Do not exercise a painful, acutely inflamed joint based on this demo. Follow your clinician’s guidance.','[]'::jsonb,'{"demo_only":true,"category":"gentle movement","topic_tags":["sleep-better","gout-uric-acid"],"fixture_label":"TEST ONLY - NOT HUMAN REVIEWED"}'::jsonb,'test-fixture',now()),
 ('hc-demo-mobility',1,'TEST ONLY: Gentle mobility','Movement-learning example only; this fixture contains no routine, range, repetitions or therapeutic promise.','activity','not_assessed','TEST ONLY. No effect or suitability assessed.','[]'::jsonb,'Avoid movement that aggravates pain; an acutely inflamed joint needs clinician-specific guidance.','[]'::jsonb,'{"demo_only":true,"category":"mobility","topic_tags":["sleep-better","gout-uric-acid"],"fixture_label":"TEST ONLY - NOT HUMAN REVIEWED"}'::jsonb,'test-fixture',now()),
 ('hc-demo-movement-break',1,'TEST ONLY: Everyday movement break','General learning example; this fixture prescribes no movement, duration or schedule.','footprints','not_assessed','TEST ONLY. No effect or suitability assessed.','[]'::jsonb,'Do not use this card to guide movement during a painful flare.','[]'::jsonb,'{"demo_only":true,"category":"everyday movement","topic_tags":["sleep-better","gout-uric-acid"],"fixture_label":"TEST ONLY - NOT HUMAN REVIEWED"}'::jsonb,'test-fixture',now()),
 ('hc-demo-wind-down',1,'TEST ONLY: Sleep wind-down habit','Learning example about evening routines; no routine is prescribed and no insomnia treatment claim is made.','moon','not_assessed','TEST ONLY. No sleep outcome or treatment effect assessed.','[]'::jsonb,'Not a substitute for assessment of persistent sleep difficulty.','[]'::jsonb,'{"demo_only":true,"category":"sleep habit","topic_tags":["sleep-better","gout-uric-acid"],"fixture_label":"TEST ONLY - NOT HUMAN REVIEWED"}'::jsonb,'test-fixture',now()),
 ('hc-demo-breath-awareness',1,'TEST ONLY: Breathing awareness','Mindfulness-literacy example with no breathing pattern, hold, timing or medical effect prescribed.','wind','not_assessed','TEST ONLY. No outcome or efficacy claim.','[]'::jsonb,'Stop if uncomfortable; this is not breathing instruction or treatment.','[]'::jsonb,'{"demo_only":true,"category":"breathing awareness","topic_tags":["sleep-better","gout-uric-acid"],"fixture_label":"TEST ONLY - NOT HUMAN REVIEWED"}'::jsonb,'test-fixture',now()),
