-- LOCAL OWNER DEMO ONLY. Synthetic interface fixtures, not human-reviewed content.
-- Applied only by start-healthclues-owner-demo.mjs after confirming the isolated
-- Supabase API is exactly 127.0.0.1:54321. Never use as production seed data.
begin;

on conflict(id) do update set slug=excluded.slug,item_type=excluded.item_type,slot_key=excluded.slot_key,review_status='reviewed',active=true,recommendation_eligible=excluded.recommendation_eligible,current_version=1;

on conflict(catalog_item_id,version) do update set name=excluded.name,description=excluded.description,evidence_class='not_assessed',evidence_summary=excluded.evidence_summary,evidence_sources=excluded.evidence_sources,safety_notes=excluded.safety_notes,contraindications=excluded.contraindications,source_provenance=excluded.source_provenance,reviewed_by='test-fixture',reviewed_at=now();

-- Recommendation metadata is explicit and TEST ONLY. Most fixtures remain education-only;
-- the harmless demo wind-down/observation cards exercise opt-in equipment mechanics only.
update public.healthclues_catalog_item_versions set source_provenance = source_provenance || '{"goal_tags":["Build a small routine","Find interesting new information"],"preference_tags":["Everyday habits","relaxation","sleep routines"],"estimated_minutes":5,"personalization_eligibility":"eligible"}'::jsonb
where catalog_item_id='hc-demo-wind-down' and version=1;
update public.healthclues_catalog_item_versions set source_provenance = source_provenance || '{"goal_tags":["Build a small routine"],"preference_tags":["Everyday habits","gentle movement"],"estimated_minutes":10,"personalization_eligibility":"eligible","requires_known_activity_safety":true}'::jsonb
where catalog_item_id='hc-demo-walking' and version=1;
update public.healthclues_catalog_item_versions set source_provenance = source_provenance || '{"goal_tags":["Find interesting new information"],"preference_tags":["open to exploring","general wellness"],"personalization_eligibility":"eligible"}'::jsonb
where catalog_item_id='hc-demo-observation' and version=1;
update public.healthclues_catalog_item_versions set source_provenance = source_provenance || '{"goal_tags":["Build a small routine","Find interesting new information"],"preference_tags":["relaxation","mindfulness","sleep routines"],"estimated_minutes":1,"personalization_eligibility":"eligible"}'::jsonb
where catalog_item_id in ('hc-demo-breath-awareness','hc-demo-mindfulness') and version=1;
update public.healthclues_catalog_item_versions set source_provenance = source_provenance || '{"goal_tags":["Explore simple recipes"],"preference_tags":["Food & recipes","Natural ingredients"],"personalization_eligibility":"education_only"}'::jsonb
where catalog_item_id in ('hc-demo-potato','hc-demo-cherries','hc-demo-tomato','hc-demo-water') and version=1;
update public.healthclues_catalog_item_versions set source_provenance = source_provenance || '{"personalization_eligibility":"education_only","requires_medication_context":true}'::jsonb
where catalog_item_id='hc-demo-ginger' and version=1;
-- These fixtures are general literacy examples, not condition-specific recommendations.
update public.healthclues_catalog_item_versions set source_provenance = jsonb_set(source_provenance,'{topic_tags}','["general-education"]'::jsonb,true)
where catalog_item_id in ('hc-demo-tomato','hc-demo-potato','hc-demo-cherries','hc-demo-ginger','hc-demo-water','hc-demo-walking','hc-demo-mobility','hc-demo-movement-break','hc-demo-breath-awareness','hc-demo-mindfulness','hc-demo-observation','hc-demo-breathing','hc-demo-activity') and version=1;
update public.healthclues_catalog_item_versions set source_provenance = jsonb_set(source_provenance,'{topic_tags}','["sleep-better","general-education"]'::jsonb,true)
where catalog_item_id='hc-demo-wind-down' and version=1;
update public.healthclues_catalog_item_versions set source_provenance = source_provenance || '{"requires_known_food_safety":true}'::jsonb
where catalog_item_id in ('hc-demo-tomato','hc-demo-potato','hc-demo-cherries','hc-demo-ginger') and version=1;
update public.healthclues_catalog_item_versions set source_provenance = source_provenance || '{"requires_known_fluid_safety":true}'::jsonb
where catalog_item_id='hc-demo-water' and version=1;

on conflict(clue_id,version) do update set topic_key=excluded.topic_key,title=excluded.title,content=excluded.content,source_references=excluded.source_references,question_prompt=excluded.question_prompt,question_options=excluded.question_options,skill_key=excluded.skill_key,review_status='reviewed',published=true,reviewed_by='test-fixture',reviewed_at=now();

values ('hc-demo-sleep-literacy',1,'interface','TEST ONLY fixture feedback. No health conclusion is made.'),('hc-demo-gout-literacy',1,'topic','TEST ONLY fixture feedback. A selected interest is not a diagnosis.')
on conflict(clue_id,clue_version) do update set correct_option_id=excluded.correct_option_id,answer_explanation=excluded.answer_explanation;

on conflict(boss_id,version) do update set title=excluded.title,intro=excluded.intro,question_prompt=excluded.question_prompt,question_options=excluded.question_options,source_references=excluded.source_references,review_status='reviewed',published=true,reviewed_by='test-fixture',reviewed_at=now();

values ('hc-demo-sleep-gate',1,'demo','TEST ONLY fixture feedback. No clinical claim.'),('hc-demo-health-gate',1,'demo','TEST ONLY fixture feedback. No clinical claim.')
on conflict(boss_id,boss_version) do update set correct_option_id=excluded.correct_option_id,explanation=excluded.explanation;

commit;
